func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var taxableSubtotal int64
	var nonTaxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		lineTotal := line.Price * line.Qty
		if line.Taxable {
			taxableSubtotal += lineTotal
		} else {
			nonTaxableSubtotal += lineTotal
		}
	}

	// Separately discount and round each subtotal
	// Rounding: (numerator + 5000) / 10000

	// Discounted taxable subtotal
	taxableNum := taxableSubtotal * (10000 - discountBP)
	roundedTaxableSubtotal := (taxableNum + 5000) / 10000

	// Discounted non-taxable subtotal
	nonTaxableNum := nonTaxableSubtotal * (10000 - discountBP)
	roundedNonTaxableSubtotal := (nonTaxableNum + 5000) / 10000

	// Compute tax from the DISCOUNTED taxable subtotal
	// Tax = roundedTaxableSubtotal * taxBP / 10000
	// Round tax once: (numerator + 5000) / 10000
	taxNum := roundedTaxableSubtotal * taxBP
	roundedTax := (taxNum + 5000) / 10000

	// Return discounted total (sum of rounded subtotals) + rounded tax
	return roundedTaxableSubtotal + roundedNonTaxableSubtotal + roundedTax
}
