func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var taxableSubtotal int64
	var nonTaxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		lineTotal := line.Price * line.Qty
		if line.Taxable {
			taxableSubtotal += lineTotal
		} else {
			nonTaxableSubtotal += lineTotal
		}
	}

	// Rounding means nearest integer cent with half rounded up: (numerator+5000)/10000
	// Apply discount and round the taxable subtotal
	taxableNum := taxableSubtotal * (10000 - discountBP)
	discountedTaxableSubtotal := (taxableNum + 5000) / 10000

	// Apply discount and round the non-taxable subtotal
	nonTaxableNum := nonTaxableSubtotal * (10000 - discountBP)
	discountedNonTaxableSubtotal := (nonTaxableNum + 5000) / 10000

	// Compute tax from the DISCOUNTED taxable subtotal
	// Tax = discountedTaxableSubtotal * taxBP / 10000
	// Round tax once: (numerator + 5000) / 10000
	taxNum := discountedTaxableSubtotal * taxBP
	roundedTax := (taxNum + 5000) / 10000

	// Return discounted total (taxable + non-taxable) + tax
	return discountedTaxableSubtotal + discountedNonTaxableSubtotal + roundedTax
}
